    cnt = 0
    for i,ch in enumerate(S):
        if ch=='1':
            cnt+=1
        else:
            cnt=0
        left_ones[i]=cnt
    # right_twos[i]: consecutive twos starting at i (including i if S[i]=='2')
    cnt = 0
    for i in range(N-1,-1,-1):
        ch = S[i]
        if ch=='2':
            cnt+=1
        else:
            cnt=0
        right_twos[i]=cnt
    ans = 1  # at least one slash
    for i,ch in enumerate(S):
        if ch!='/':
            continue
        L = left_ones[i-1] if i>0 else 0
        R = right_twos[i+1] if i+1<N else 0
        total = L+R
        if total % 2 == 0:
            cur = total + 1
        else:
            # reduce one from side with positive count
            if L>0:
                cur = (L-1)+R+1
            elif R>0:
                cur = L+(R-1)+1
            else:
                cur = 1
        if cur>ans:
            ans=cur
    print(ans)

