import sys

def solve() -> None:
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    N = int(input_data[0])
    S = input_data[1]
    left = [0] * N
    right = [0] * N

    cnt = 0
    for i, ch in enumerate(S):
        if ch == '1':
            cnt += 1
        else:
            # at slash or '2', store count of preceding 1's
            left[i] = cnt
            cnt = 0
    # trailing 1's after last slash don't affect any slash

    cnt = 0
    for i in range(N - 1, -1, -1):
        ch = S[i]
        if ch == '2':
            cnt += 1
        else:
            # at slash or '1', store count of following 2's
            right[i] = cnt
            cnt = 0

    ans = 1  # at least one slash
    for i, ch in enumerate(S):
        if ch == '/':
            l = left[i]
            r = right[i]
            length = 2 * min(l, r) + 1
            if length > ans:
                ans = length
    print(ans)

if __name__ == "__main__":
    solve()
