import sys

def solve() -> None:
    input = sys.stdin.readline
    n_line = input().strip()
    while n_line == '':
        n_line = input().strip()
    N = int(n_line)
    S = input().strip()
    n = len(S)

    # Precompute consecutive '1's ending at each position
    left_ones = [0] * n
    for i in range(n):
        if S[i] == '1':
            left_ones[i] = (left_ones[i - 1] + 1) if i > 0 else 1
        else:
            left_ones[i] = 0

    # Precompute consecutive '2's starting at each position
    right_twos = [0] * n
    for i in range(n - 1, -1, -1):
        if S[i] == '2':
            right_twos[i] = (right_twos[i + 1] + 1) if i < n - 1 else 1
        else:
            right_twos[i] = 0

    ans = 1  # at least the slash itself
    for i, ch in enumerate(S):
        if ch == '/':
            left = left_ones[i - 1] if i > 0 else 0
            right = right_twos[i + 1] if i + 1 < n else 0
            k = left if left < right else right
            length = 2 * k + 1
            if length > ans:
                ans = length

    print(ans)

if __name__ == "__main__":
    solve()
